input.command:
cd "/c/Users/Jaidityaa Jain/OneDrive/Desktop/TechSparks" && python - <<'EOF'
import re
homes={}
for line in open('research_notes/dtx-story/S1-fact-homes.md',encoding='utf-8'):
    m=re.match(r'\| (D\d-\d+-F\d+) \| (\w) \|',line)
    if m: homes[m.group(1)]=m.group(2)
def norm(i):
    a,b,c=re.match(r'(D\d)-(\d+)-F(\d+)',i).groups()
    return f"{a}-{b}-F{int(c)}"
src={}
for p in ['40-engineer','50-players','70-funded','55-money']:
    t=open(f'report-parts/dtx/{p}.md',encoding='utf-8').read()
    src[p]=set(norm(x) for x in re.findall(r'D\d-\d+-F\d+',t))
allsrc=set().union(*src.values())
for L in 'CDE':
    ids=[k for k,v in homes.items() if v==L]
    missing=[i for i in ids if i not in allsrc]
    print(L,len(ids),'missing from my sources:',missing)
others=sorted(i for i in allsrc if homes.get(i) not in ('C','D','E'))
print('other-home IDs in my sources:')
for i in others: print(i,homes.get(i), [p for p in src if i in src[p]])
EOF

